+// shellArguments evaluates quoted in /bin/sh as the arguments of one command, in dir, and
+// returns how many arguments it produced and the first one.
+func shellArguments(t *testing.T, dir, quoted string) (string, string) {
+	t.Helper()
+	cmd := exec.Command("/bin/sh", "-c", "set -- "+quoted+"\nprintf '%s\\n' \"$#\"\nprintf '%s' \"$1\"")
+	cmd.Dir = dir
+	out, err := cmd.Output()
+	if err != nil {
+		t.Fatalf("/bin/sh evaluating %q: %v", quoted, err)
+	}
+	count, first, _ := strings.Cut(string(out), "\n")
+	return count, first
+}
+
+func TestShellQuoteGivesOneLiteralArgument(t *testing.T) {
+	parallel(t)
+	for _, value := range []string{"", "a b", "  leading and trailing  ", "it's", "'", "''", "a'b'c"} {
+		count, first := shellArguments(t, t.TempDir(), ShellQuote(value))
+		shpEq(t, fmt.Sprintf("argument count of %q", value), count, "1")
+		shpEq(t, fmt.Sprintf("argument for %q", value), first, value)
+	}
+}
+
+func TestShellQuoteKeepsCommandSubstitutionLiteral(t *testing.T) {
+	parallel(t)
+	for _, value := range []string{"$(>marker)", "`>marker`", "$HOME", "${HOME}", ";>marker", "&&>marker", "|>marker", "*", `\`, `"$(>marker)"`} {
+		dir := t.TempDir()
+		count, first := shellArguments(t, dir, ShellQuote(value))
+		shpEq(t, fmt.Sprintf("argument count of %q", value), count, "1")
+		shpEq(t, fmt.Sprintf("argument for %q", value), first, value)
+		if _, err := os.Stat(filepath.Join(dir, "marker")); err == nil {
+			t.Fatalf("evaluating the quoted %q executed its content", value)
+		}
+	}
+}
+
+func TestShellQuoteKeepsLineBreaks(t *testing.T) {
+	parallel(t)
+	for _, value := range []string{"a\nb", "\n", "first\nsecond\n", "a\r\nb", "a\n\nb"} {
+		count, first := shellArguments(t, t.TempDir(), ShellQuote(value))
+		shpEq(t, fmt.Sprintf("argument count of %q", value), count, "1")
+		shpEq(t, fmt.Sprintf("argument for %q", value), first, value)
+	}
+}

